import Foundation
final class PrintSlot {
    private let lock = NSLock()
    func upload(maxAttempts: Int, work: () -> Void) -> Bool {
        for _ in 0..<max(0, maxAttempts) {
            if lock.try() {
                defer { lock.unlock() }
                work()
                return true
            }
        }
        return false
    }
}
let slot = PrintSlot()
print(slot.upload(maxAttempts: 2) { print("Фотокнига") })
print(slot.upload(maxAttempts: 0) { print("Фотокнига") })

Вывод «Фотокнига», true, затем false без печати. Бюджет гарантирует выход и честный статус caller-у, но не успех: при занятом слоте все попытки вернут false. В реальном коде между попытками ждут события готовности, а не крутят цикл подряд.
